//! Rust translation of `reference/version.py` (python-semver), covering the
//! subset of behaviour expressible through the fixed contract: parsing,
//! canonical formatting, semver precedence comparison and the three
//! numeric bump operations.
//!
//! Prerelease and build metadata are validated against the same grammar as
//! the Python `_REGEX` (ASCII only, `re.ASCII`), and precedence follows the
//! natural-comparison algorithm from `Version._nat_cmp` / `Version.compare`.

use std::cmp::Ordering;

/// A parsed semantic version.
///
/// `prerelease` and `build` hold the text *after* the `-` and `+`
/// respectively, with the separator stripped, or `None` when absent.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Version {
    pub major: u64,
    pub minor: u64,
    pub patch: u64,
    pub prerelease: Option<String>,
    pub build: Option<String>,
}

/// A numeric core component (`major`, `minor` or `patch`) is valid if it is
/// either exactly `"0"` or matches `[1-9]\d*` (no leading zeroes).
fn is_valid_numeric(s: &str) -> bool {
    !s.is_empty()
        && s.chars().all(|c| c.is_ascii_digit())
        && (s.len() == 1 || !s.starts_with('0'))
}

/// A prerelease identifier is valid if it matches
/// `0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*` (ASCII only).
fn is_valid_prerelease_identifier(s: &str) -> bool {
    if s.is_empty() {
        return false;
    }
    if !s.chars().all(|c| c.is_ascii_alphanumeric() || c == '-') {
        return false;
    }
    let all_digits = s.chars().all(|c| c.is_ascii_digit());
    if all_digits {
        s.len() == 1 || !s.starts_with('0')
    } else {
        true
    }
}

/// A build identifier is valid if it matches `[0-9a-zA-Z-]+` (ASCII only).
fn is_valid_build_identifier(s: &str) -> bool {
    !s.is_empty() && s.chars().all(|c| c.is_ascii_alphanumeric() || c == '-')
}

/// Parse a version string. Return `Err` with a short reason for anything
/// that is not a valid semver 2.0.0 string.
///
/// Reject, among others: leading zeroes (`01.0.0`), missing components
/// (`1.0`), negative numbers, empty identifiers (`1.0.0-`), and whitespace.
pub fn parse(s: &str) -> Result<Version, String> {
    let invalid = || format!("{s} is not valid SemVer string");

    // The first '+' (if any) always starts the build metadata section,
    // because none of the earlier grammar productions may contain '+'.
    let (before_build, build_opt) = match s.find('+') {
        Some(i) => (&s[..i], Some(&s[i + 1..])),
        None => (s, None),
    };
    // Within what remains, the first '-' (if any) starts the prerelease
    // section, because the numeric core cannot contain '-'.
    let (core, prerelease_opt) = match before_build.find('-') {
        Some(i) => (&before_build[..i], Some(&before_build[i + 1..])),
        None => (before_build, None),
    };

    let parts: Vec<&str> = core.split('.').collect();
    if parts.len() != 3 {
        return Err(invalid());
    }
    for p in &parts {
        if !is_valid_numeric(p) {
            return Err(invalid());
        }
    }
    let major: u64 = parts[0].parse().map_err(|_| invalid())?;
    let minor: u64 = parts[1].parse().map_err(|_| invalid())?;
    let patch: u64 = parts[2].parse().map_err(|_| invalid())?;

    let prerelease = match prerelease_opt {
        None => None,
        Some(pr) => {
            if pr.is_empty() {
                return Err(invalid());
            }
            for ident in pr.split('.') {
                if !is_valid_prerelease_identifier(ident) {
                    return Err(invalid());
                }
            }
            Some(pr.to_string())
        }
    };
    let build = match build_opt {
        None => None,
        Some(b) => {
            if b.is_empty() {
                return Err(invalid());
            }
            for ident in b.split('.') {
                if !is_valid_build_identifier(ident) {
                    return Err(invalid());
                }
            }
            Some(b.to_string())
        }
    };

    Ok(Version {
        major,
        minor,
        patch,
        prerelease,
        build,
    })
}

/// Render a `Version` back to its canonical string form.
/// `parse(&to_string(&v))` must round-trip for every valid `v`.
pub fn to_string(v: &Version) -> String {
    let mut out = format!("{}.{}.{}", v.major, v.minor, v.patch);
    if let Some(pre) = &v.prerelease {
        if !pre.is_empty() {
            out.push('-');
            out.push_str(pre);
        }
    }
    if let Some(build) = &v.build {
        if !build.is_empty() {
            out.push('+');
            out.push_str(build);
        }
    }
    out
}

/// Compare two dot-separated digit strings as arbitrary-precision, unsigned
/// integers (no assumption of bounded width, mirroring Python's `int`).
fn cmp_numeric_str(a: &str, b: &str) -> Ordering {
    let ta = a.trim_start_matches('0');
    let tb = b.trim_start_matches('0');
    let ta = if ta.is_empty() { "0" } else { ta };
    let tb = if tb.is_empty() { "0" } else { tb };
    if ta.len() != tb.len() {
        ta.len().cmp(&tb.len())
    } else {
        ta.cmp(tb)
    }
}

/// Natural comparison of two prerelease strings, mirroring
/// `Version._nat_cmp`: dot-separated parts are compared pairwise, numeric
/// parts always rank below non-numeric ones, and if all compared parts are
/// equal the string with more parts wins.
fn nat_cmp(a: &str, b: &str) -> Ordering {
    let a_parts: Vec<&str> = a.split('.').collect();
    let b_parts: Vec<&str> = b.split('.').collect();

    for (pa, pb) in a_parts.iter().zip(b_parts.iter()) {
        let is_a_num = !pa.is_empty() && pa.chars().all(|c| c.is_ascii_digit());
        let is_b_num = !pb.is_empty() && pb.chars().all(|c| c.is_ascii_digit());
        let ord = match (is_a_num, is_b_num) {
            (true, true) => cmp_numeric_str(pa, pb),
            (true, false) => Ordering::Less,
            (false, true) => Ordering::Greater,
            (false, false) => pa.cmp(pb),
        };
        if ord != Ordering::Equal {
            return ord;
        }
    }
    a_parts.len().cmp(&b_parts.len())
}

/// Semver precedence.
///
/// Careful — this is where naive translations break:
///   * build metadata is IGNORED entirely for precedence
///   * a version WITH a prerelease is LOWER than the same version without
///   * prerelease identifiers compare left to right, dot-separated
///   * all-numeric identifiers compare numerically
///   * all other identifiers compare lexically in ASCII order
///   * numeric identifiers always rank LOWER than non-numeric ones
///   * if all preceding identifiers are equal, more identifiers wins
///
/// The spec's own worked example, which you should be able to reproduce:
///   1.0.0-alpha < 1.0.0-alpha.1 < 1.0.0-alpha.beta < 1.0.0-beta
///     < 1.0.0-beta.2 < 1.0.0-beta.11 < 1.0.0-rc.1 < 1.0.0
pub fn compare(a: &Version, b: &Version) -> Ordering {
    let core_cmp = (a.major, a.minor, a.patch).cmp(&(b.major, b.minor, b.patch));
    if core_cmp != Ordering::Equal {
        return core_cmp;
    }

    let a_pre = a.prerelease.as_deref().unwrap_or("");
    let b_pre = b.prerelease.as_deref().unwrap_or("");
    let rccmp = nat_cmp(a_pre, b_pre);
    if rccmp == Ordering::Equal {
        return Ordering::Equal;
    }
    let rc1_falsy = a.prerelease.as_deref().map_or(true, |s| s.is_empty());
    let rc2_falsy = b.prerelease.as_deref().map_or(true, |s| s.is_empty());
    if rc1_falsy {
        return Ordering::Greater;
    }
    if rc2_falsy {
        return Ordering::Less;
    }
    rccmp
}

/// Increment major; reset minor and patch; drop prerelease and build.
pub fn bump_major(v: &Version) -> Version {
    Version {
        major: v.major.saturating_add(1),
        minor: 0,
        patch: 0,
        prerelease: None,
        build: None,
    }
}

/// Increment minor; reset patch; drop prerelease and build.
pub fn bump_minor(v: &Version) -> Version {
    Version {
        major: v.major,
        minor: v.minor.saturating_add(1),
        patch: 0,
        prerelease: None,
        build: None,
    }
}

/// Increment patch; drop prerelease and build.
///
/// Do not guess the prerelease interaction — read `reference/version.py`
/// and check against the oracle. `evaluate.py` compares you to the real
/// `semver` package on every bump of every valid version it generates.
pub fn bump_patch(v: &Version) -> Version {
    Version {
        major: v.major,
        minor: v.minor,
        patch: v.patch.saturating_add(1),
        prerelease: None,
        build: None,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_parse_basic_version() -> Result<(), String> {
        let v = parse("1.2.3-alpha.1.2+build.11.e0f985a")?;
        assert_eq!(
            v,
            Version {
                major: 1,
                minor: 2,
                patch: 3,
                prerelease: Some("alpha.1.2".to_string()),
                build: Some("build.11.e0f985a".to_string()),
            }
        );
        Ok(())
    }

    #[test]
    fn test_parse_hyphen_prerelease() -> Result<(), String> {
        let v = parse("1.2.3-alpha-1+build.11.e0f985a")?;
        assert_eq!(
            v,
            Version {
                major: 1,
                minor: 2,
                patch: 3,
                prerelease: Some("alpha-1".to_string()),
                build: Some("build.11.e0f985a".to_string()),
            }
        );
        Ok(())
    }

    #[test]
    fn test_parse_zero_prefixed_alnum_prerelease() -> Result<(), String> {
        let v = parse("0.1.0-0f")?;
        assert_eq!(
            v,
            Version {
                major: 0,
                minor: 1,
                patch: 0,
                prerelease: Some("0f".to_string()),
                build: None,
            }
        );
        Ok(())
    }

    #[test]
    fn test_parse_zero_prerelease_multi() -> Result<(), String> {
        let v = parse("0.0.0-0foo.1")?;
        assert_eq!(
            v,
            Version {
                major: 0,
                minor: 0,
                patch: 0,
                prerelease: Some("0foo.1".to_string()),
                build: None,
            }
        );
        Ok(())
    }

    #[test]
    fn test_parse_zero_prerelease_with_build() -> Result<(), String> {
        let v = parse("0.0.0-0foo.1+build.1")?;
        assert_eq!(
            v,
            Version {
                major: 0,
                minor: 0,
                patch: 0,
                prerelease: Some("0foo.1".to_string()),
                build: Some("build.1".to_string()),
            }
        );
        Ok(())
    }

    #[test]
    fn test_reject_zero_prefixed_components() {
        for bad in ["01.2.3", "1.02.3", "1.2.03"] {
            assert!(parse(bad).is_err(), "expected {bad} to be rejected");
        }
    }

    #[test]
    fn test_reject_invalid_versions() {
        for bad in ["foo", "1.0", "1.x", "1.0.0-"] {
            assert!(parse(bad).is_err(), "expected {bad} to be rejected");
        }
    }

    #[test]
    fn test_round_trip_format() -> Result<(), String> {
        for s in [
            "1.2.3",
            "1.2.3-rc.1",
            "1.2.3+build.4",
            "1.2.3-rc.1+build.4",
            "0.0.0-0foo.1+build.1",
        ] {
            let v = parse(s)?;
            assert_eq!(to_string(&v), s);
        }
        Ok(())
    }

    #[test]
    fn test_less_chain() -> Result<(), String> {
        let pairs = [
            ("1.0.0", "2.0.0"),
            ("1.0.0-alpha", "1.0.0-alpha.1"),
            ("1.0.0-alpha.1", "1.0.0-alpha.beta"),
            ("1.0.0-alpha.beta", "1.0.0-beta"),
            ("1.0.0-beta", "1.0.0-beta.2"),
            ("1.0.0-beta.2", "1.0.0-beta.11"),
            ("1.0.0-beta.11", "1.0.0-rc.1"),
            ("1.0.0-rc.1", "1.0.0"),
        ];
        for (l, r) in pairs {
            let lv = parse(l)?;
            let rv = parse(r)?;
            assert_eq!(compare(&lv, &rv), Ordering::Less, "{l} vs {r}");
        }
        Ok(())
    }

    #[test]
    fn test_greater_chain() -> Result<(), String> {
        let pairs = [
            ("2.0.0", "1.0.0"),
            ("1.0.0-alpha.1", "1.0.0-alpha"),
            ("1.0.0-alpha.beta", "1.0.0-alpha.1"),
            ("1.0.0-beta", "1.0.0-alpha.beta"),
            ("1.0.0-beta.2", "1.0.0-beta"),
            ("1.0.0-beta.11", "1.0.0-beta.2"),
            ("1.0.0-rc.1", "1.0.0-beta.11"),
            ("1.0.0", "1.0.0-rc.1"),
        ];
        for (l, r) in pairs {
            let lv = parse(l)?;
            let rv = parse(r)?;
            assert_eq!(compare(&lv, &rv), Ordering::Greater, "{l} vs {r}");
        }
        Ok(())
    }

    #[test]
    fn test_specification_chain() -> Result<(), String> {
        let chain = [
            "1.0.0-alpha",
            "1.0.0-alpha.1",
            "1.0.0-beta.2",
            "1.0.0-beta.11",
            "1.0.0-rc.1",
            "1.0.0",
            "1.3.7+build",
        ];
        for w in chain.windows(2) {
            let lo = parse(w[0])?;
            let hi = parse(w[1])?;
            assert_eq!(compare(&lo, &hi), Ordering::Less);
            assert_eq!(compare(&hi, &lo), Ordering::Greater);
        }
        Ok(())
    }

    #[test]
    fn test_compare_rc_builds() -> Result<(), String> {
        let l = parse("1.0.0-beta.2")?;
        let r = parse("1.0.0-beta.11")?;
        assert_eq!(compare(&l, &r), Ordering::Less);
        Ok(())
    }

    #[test]
    fn test_compare_rc_with_release() -> Result<(), String> {
        for (l, r) in [("1.0.0-rc.1", "1.0.0"), ("1.0.0-rc.1+build.1", "1.0.0")] {
            let lv = parse(l)?;
            let rv = parse(r)?;
            assert_eq!(compare(&lv, &rv), Ordering::Less);
        }
        Ok(())
    }

    #[test]
    fn test_equal_versions() -> Result<(), String> {
        for (l, r) in [
            ("2.0.0", "2.0.0"),
            ("1.1.9-rc.1", "1.1.9-rc.1"),
            ("1.1.9+build.1", "1.1.9+build.1"),
            ("1.1.9-rc.1+build.1", "1.1.9-rc.1+build.1"),
        ] {
            let lv = parse(l)?;
            let rv = parse(r)?;
            assert_eq!(compare(&lv, &rv), Ordering::Equal);
        }
        Ok(())
    }

    #[test]
    fn test_compare_versions_with_build_and_release() -> Result<(), String> {
        let a = parse("1.1.9-rc.1")?;
        let b = parse("1.1.9-rc.1+build.1")?;
        assert_eq!(compare(&a, &b), Ordering::Equal);
        let c = parse("1.1.9+build.1")?;
        assert_eq!(compare(&a, &c), Ordering::Less);
        Ok(())
    }

    #[test]
    fn test_ignore_builds_on_compare() -> Result<(), String> {
        let cases = [
            ("1.0.0+build.1", "1.0.0", Ordering::Equal),
            ("1.0.0-alpha.1+build.1", "1.0.0-alpha.1", Ordering::Equal),
            ("1.0.0+build.1", "1.0.0-alpha.1", Ordering::Greater),
            ("1.0.0+build.1", "1.0.0-alpha.1+build.1", Ordering::Greater),
        ];
        for (l, r, expected) in cases {
            let lv = parse(l)?;
            let rv = parse(r)?;
            assert_eq!(compare(&lv, &rv), expected, "{l} vs {r}");
        }
        Ok(())
    }

    #[test]
    fn test_more_rc1() -> Result<(), String> {
        let l = parse("1.0.0-rc1")?;
        let r = parse("1.0.0-rc0")?;
        assert_eq!(compare(&l, &r), Ordering::Greater);
        Ok(())
    }

    #[test]
    fn test_compare_prerelease_numbers_letters() -> Result<(), String> {
        let v1 = Version {
            major: 1,
            minor: 9,
            patch: 1,
            prerelease: Some("1unms".to_string()),
            build: None,
        };
        let v2 = Version {
            major: 1,
            minor: 9,
            patch: 1,
            prerelease: None,
            build: Some("1asd".to_string()),
        };
        assert_eq!(compare(&v1, &v2), Ordering::Less);

        let a = parse("1.9.1-1unms")?;
        let b = parse("1.9.1+1")?;
        assert_eq!(compare(&a, &b), Ordering::Less);
        Ok(())
    }

    #[test]
    fn test_bump_major_minor_patch_basic() -> Result<(), String> {
        let v = parse("3.4.5")?;
        assert_eq!(to_string(&bump_major(&v)), "4.0.0");
        assert_eq!(to_string(&bump_minor(&v)), "3.5.0");
        assert_eq!(to_string(&bump_patch(&v)), "3.4.6");
        Ok(())
    }

    #[test]
    fn test_bump_major_then_minor_chain() -> Result<(), String> {
        let v = parse("3.4.5")?;
        let bumped = bump_minor(&bump_major(&v));
        let expected = parse("4.1.0")?;
        assert_eq!(bumped, expected);
        Ok(())
    }

    #[test]
    fn test_bump_minor_then_patch_chain_compare() -> Result<(), String> {
        let v = parse("3.4.5")?;
        let bumped = bump_patch(&bump_minor(&v));
        let expected = parse("3.5.1")?;
        assert_eq!(bumped, expected);
        assert_eq!(compare(&v, &expected), Ordering::Less);
        Ok(())
    }

    #[test]
    fn test_bump_ignore_extensions() -> Result<(), String> {
        let v = parse("3.4.5-rc1+build4")?;
        assert_eq!(to_string(&bump_patch(&v)), "3.4.6");
        Ok(())
    }

    #[test]
    fn test_bump_drops_prerelease_and_build() -> Result<(), String> {
        let v = parse("1.2.3-rc.1+build.9")?;
        let bumped = bump_major(&v);
        assert_eq!(bumped.prerelease, None);
        assert_eq!(bumped.build, None);
        Ok(())
    }
}
